CREATE TABLE raw_sf_per_person (
  person_id_external   VARCHAR,
  date_of_birth        DATE, -- sensitive PII
  country_of_birth     VARCHAR,
  _loaded_at           TIMESTAMP
);

CREATE TABLE raw_sf_emp_employment (
  user_id              VARCHAR,
  person_id_external   VARCHAR,
  start_date           DATE,
  end_date             DATE,
  original_start_date  DATE,
  _loaded_at           TIMESTAMP
);

CREATE TABLE raw_sf_per_email (
  person_id_external   VARCHAR,
  email_address        VARCHAR, -- workforce PII
  is_primary           BOOLEAN,
  _loaded_at           TIMESTAMP
);

CREATE TABLE raw_freshdesk_conversation_meta (
  conversation_id      BIGINT,
  ticket_id            BIGINT,
  created_at           TIMESTAMP,
  user_id              BIGINT,
  private              BOOLEAN,
  _loaded_at           TIMESTAMP
  -- no body/body_text
);

CREATE TABLE raw_freshdesk_agent (
  agent_id             BIGINT,
  email                VARCHAR, -- workforce PII
  active               BOOLEAN,
  _loaded_at           TIMESTAMP
);

CREATE TABLE raw_epic_appointment (
  appointment_id       VARCHAR,
  patient_token        VARCHAR, -- tokenized
  department_id        VARCHAR,
  scheduled_at         TIMESTAMP,
  status               VARCHAR, -- booked | arrived | noshow | cancelled
  _loaded_at           TIMESTAMP
  -- no free-text appointment reason
);

CREATE TABLE raw_epic_diagnosis_code (
  encounter_id         VARCHAR,
  icd_code             VARCHAR, -- code only, not description text
  _loaded_at           TIMESTAMP
);

CREATE TABLE raw_epic_procedure_code (
  encounter_id         VARCHAR,
  cpt_code             VARCHAR, -- code only, not description text
  _loaded_at           TIMESTAMP
);
